// API Gateway using Netflix's Zuul

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cloud.netflix.zuul.filters.discovery.PatternServiceRouteMapper;
import org.springframework.cloud.netflix.zuul.filters.discovery.ServiceRouteMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class ZuulConfig {
    @Bean
    public ServiceRouteMapper serviceRouteMapper() {
        return new PatternServiceRouteMapper(
                "^(?)<name>^(?<name>^.+)$",
                "${name}.com"
        );
    }
}

@RestController
public class ApiGatewayController {
    @Autowired
    private RestTemplate restTemplate;

    @GetMapping("/users/{id}")
    public String getUser(@PathVariable Long id) {
        // Route request to user service
        String userServiceUrl = "http://user-service/users/{id}";
        return restTemplate.getForObject(userServiceUrl, String.class, id);
    }
}
```

**Authorization Service (Microservice)**
```java
// Authorization Service using Spring Boot with Spring Security

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;

@RestController
public class AuthorizationController {
    @Autowired
    private JwtTokenValidator jwtTokenValidator;

    @GetMapping("/permissions")
    @PreAuthorize("hasRole('ROLE_USER')")
    public String getPermissions() {
        // Validate JWT token
        String token = jwtTokenValidator.getToken();
        Claims claims = Jwts.parser()
                .setSigningKey("secret-key")
                .parseClaimsJws(token)
                .getBody();

        // Check user permissions
        String username = claims.getSubject();
        // Return user permissions
        return "User " + username + " has ROLE_USER permission";
    }
}

// JWT token validator
@Component
public class JwtTokenValidator {
    @Value("${jwt.secret}")
    private String secret;

    public String getToken() {
        // Get JWT token from request header
        String token = request.getHeader("Authorization");
        return token;
    }

    public boolean validateToken(String token) {
        try {
            Claims claims = Jwts.parser()
                    .setSigningKey(secret)
                    .parseClaimsJws(token)
                    .getBody();
            return true;
        } catch (JwtException e) {
            return false;
        }
    }
}
```

**Event Producer**
```java
// Event Producer using Apache Kafka

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.Properties;

@Component
public class EventProducer {
    @Autowired
    private KafkaConfig kafkaConfig;

    public void produceEvent(String topic, String event) {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, kafkaConfig.getBootstrapServers());
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());

        KafkaProducer<String, String> producer = new KafkaProducer<>(props);
        ProducerRecord<String, String> record = new ProducerRecord<>(topic, event);
        producer.send(record);
        producer.flush();
    }
}

// Kafka config
@Configuration
public class KafkaConfig {
    @Value("${kafka.bootstrap.servers}")
    private String bootstrapServers;

    public String getBootstrapServers() {
        return bootstrapServers;
    }
}
```

